    smooth();
    for(var i = 0; i < TWO_PI; i+=TWO_PI/numParticles) {
        var p = new Particle(width/2 + cos(i)*circleRadius, height/2 + sin(i) * circleRadius);
        particles.push(p);
    }
    fill(0);
    ellipseMode(CENTER);
    ellipse(width/2, height/2, circleRadius*2);
}

