// === Tab: utils ===

function bezierControlFromNoise(x, y, amplitude) {
     var angle = map(noise(x/noiseScale, y/noiseScale,nz), 0, 1, 0, 180);
     var length = map(noise(x/noiseScale, y/noiseScale, nz), 0, 1, 0, amplitude);
     return {
       x: x + Math.cos(angle) * length,
       y: y + Math.sin(angle) * length
     };
   }

function sqDirFromNoise(x, y) {
    var dirAngle = Math.floor(map(noise(x/noiseScale, y/noiseScale, nz), 0, 1, 0, nbDivision));
    dirAngle = (dirAngle * (TWO_PI/nbDivision) * 2) - TWO_PI;
    return dirAngle;
}

function dirFromNoiseCustomSections(x, y, sections) {
     var dirIndex = Math.floor(map(noise(x/noiseScale, y/noiseScale), 0, 1, 0, sections));
     return dirIndex * (TWO_PI/sections);
   }

function dirFromNoise(x, y) {
    var dirAngle = map(noise(x/noiseScale, y/noiseScale, nz), 0, 1, -TWO_PI, TWO_PI);
    return dirAngle;
}

function curlNoise(x, y) {
    const eps = 1.0/noiseScale;
    let n1, n2, a, b;
    x = x / noiseScale;
    y = y / noiseScale;
    n1 = noise(x, y + eps, nz);
    n2 = noise(x, y - eps, nz);
    a = (n1 - n2) / (2 * eps);

    n1 = noise(x + eps, y, nz);
    n2 = noise(x - eps, y, nz);

    b = (n1 - n2)/(2 * eps);

    var curl = createVector(a, -b);
    curl.normalize();
    return curl;
}

function curlNoiseFloored(x, y) {
	  // curl operator
    var eps = 1.0/noiseScale;
    noiseDetail(2, .5);
    var n1, n2, a, b;
    x = x / noiseScale;
    y = y / noiseScale;
    n1 = noise(x, y + eps, nz);
    n2 = noise(x, y - eps, nz);
    a = (n1 - n2) / (2 * eps);

    n1 = noise(x + eps, y, nz);
    n2 = noise(x - eps, y, nz);

    b = (n1 - n2)/(2 * eps);

    var curl = createVector(a, -b);

    var angle = curl.heading();
		// degrees of freedom
    var dof = 6;
	  // floor the angle into one of the predetermined available angles
    var flooredangle = TWO_PI * (floor((angle / TWO_PI)*dof)/float(dof));
    curl = p5.Vector.fromAngle(flooredangle);
    // curl.normalize();
    return curl;
}

